import{_ as l,a0 as r,w as a,s as d,I as n,x as t,a1 as s,A as o,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"Linux有问必答：Linux上如何安装Shrew Soft IPsec VPN | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：Linux上如何安装Shrew Soft IPsec VPN | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：Linux上如何安装Shrew Soft IPsec VPN | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：Linux上如何安装Shrew Soft IPsec VPN | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150506 Linux FAQs with Answers--How to install Shrew Soft IPsec VPN client on Linux","title":"Linux有问必答：Linux上如何安装Shrew Soft IPsec VPN","tag":"201506","desc":""},"relativePath":"201506/20150506 Linux FAQs with Answers--How to install Shrew Soft IPsec VPN client on Linux.md","filePath":"[post].md"}'),u={name:"201506/20150506 Linux FAQs with Answers--How to install Shrew Soft IPsec VPN client on Linux.md"};function f(w,e,x,h,P,c){const i=r("Link");return a(),d("div",null,[e[16]||(e[16]=n("h1",{id:"linux有问必答-linux上如何安装shrew-soft-ipsec-vpn",tabindex:"-1"},[t("Linux有问必答：Linux上如何安装Shrew Soft IPsec VPN "),n("a",{class:"header-anchor",href:"#linux有问必答-linux上如何安装shrew-soft-ipsec-vpn","aria-label":"Permalink to “Linux有问必答：Linux上如何安装Shrew Soft IPsec VPN”"},"​")],-1)),e[17]||(e[17]=n("blockquote",null,[n("p",null,[n("strong",null,"问题"),t("：我需要连接到一个IPSec VPN网关，鉴于此，我尝试使用Shrew Soft VPN客户端，它是一个免费版本。我怎样才能安装Shrew Soft VPN客户端到[某个Linux发行版]?")])],-1)),e[18]||(e[18]=n("p",null,"市面上有许多商业VPN网关，同时附带有他们自己的专有VPN客户端软件。虽然也有许多开源的VPN服务器/客户端备选方案，但它们通常缺乏复杂的IPsec支持，比如互联网密钥交换（IKE），这是一个标准的IPsec协议，用于加固VPN密钥交换和验证安全。Shrew Soft VPN是一个免费的IPsec VPN客户端，它支持多种验证方法、密钥交换、加密以及防火墙穿透选项。",-1)),e[19]||(e[19]=n("p",null,"下面介绍如何安装Shrew Soft VPN客户端到Linux平台。",-1)),n("p",null,[e[1]||(e[1]=t("首先，从",-1)),s(i,{href:"https://www.shrew.net/download/ike"},{default:o(()=>[...e[0]||(e[0]=[t("官方站点",-1)])]),_:1}),e[2]||(e[2]=t("下载它的源代码。",-1))]),e[20]||(e[20]=p(`<h3 id="安装shrew-vpn客户端到debian-ubuntu或者linux-mint" tabindex="-1">安装Shrew VPN客户端到Debian, Ubuntu或者Linux Mint <a class="header-anchor" href="#安装shrew-vpn客户端到debian-ubuntu或者linux-mint" aria-label="Permalink to “安装Shrew VPN客户端到Debian, Ubuntu或者Linux Mint”">​</a></h3><p>Shrew Soft VPN客户端图形界面要求使用Qt 4.x。所以，作为依赖，你需要安装其开发文件。</p><pre><code>$ sudo apt-get install cmake libqt4-core libqt4-dev libqt4-gui libedit-dev libssl-dev checkinstall flex bison
$ wget https://www.shrew.net/download/ike/ike-2.2.1-release.tbz2
$ tar xvfvj ike-2.2.1-release.tbz2
$ cd ike
$ cmake -DCMAKE_INSTALL_PREFIX=/usr -DQTGUI=YES -DETCDIR=/etc -DNATT=YES .
$ make
$ sudo make install
$ cd /etc/
$ sudo mv iked.conf.sample iked.conf 
</code></pre><h3 id="安装shrew-vpn客户端到centos-fedora或者rhel" tabindex="-1">安装Shrew VPN客户端到CentOS, Fedora或者RHEL <a class="header-anchor" href="#安装shrew-vpn客户端到centos-fedora或者rhel" aria-label="Permalink to “安装Shrew VPN客户端到CentOS, Fedora或者RHEL”">​</a></h3><p>与基于Debian的系统类似，在编译前你需要安装一堆依赖包，包括Qt4。</p><pre><code>$ sudo yum install qt-devel cmake gcc-c++ openssl-devel libedit-devel flex bison
$ wget https://www.shrew.net/download/ike/ike-2.2.1-release.tbz2
$ tar xvfvj ike-2.2.1-release.tbz2
$ cd ike
$ cmake -DCMAKE_INSTALL_PREFIX=/usr -DQTGUI=YES -DETCDIR=/etc -DNATT=YES .
$ make
$ sudo make install
$ cd /etc/
$ sudo mv iked.conf.sample iked.conf 
</code></pre><p>在基于Red Hat的系统中，最后一步需要用文本编辑器打开/etc/ld.so.conf文件，并添加以下行。</p><pre><code>$ sudo vi /etc/ld.so.conf
</code></pre><hr><pre><code>include /usr/lib/
</code></pre><p>重新加载运行时绑定的共享库文件，以容纳新安装的共享库：</p><pre><code>$ sudo ldconfig 
</code></pre><h3 id="启动shrew-vpn客户端" tabindex="-1">启动Shrew VPN客户端 <a class="header-anchor" href="#启动shrew-vpn客户端" aria-label="Permalink to “启动Shrew VPN客户端”">​</a></h3><p>首先，启动IKE守护进程（iked）。该守护进作为VPN客户端程通过IKE协议与远程主机经由IPSec通信。</p><pre><code>$ sudo iked 
</code></pre><p><img src="https://farm9.staticflickr.com/8685/17175688940_59c2db64c9_b.jpg" alt=""></p><p>现在，启动qikea，它是一个IPsec VPN客户端前端。该GUI应用允许你管理远程站点配置并初始化VPN连接。</p><p><img src="https://farm8.staticflickr.com/7750/16742992713_eed7f97939_b.jpg" alt=""></p><p>要创建一个新的VPN配置，点击“添加”按钮，然后填入VPN站点配置。创建配置后，你可以通过点击配置来初始化VPN连接。</p><p><img src="https://farm8.staticflickr.com/7725/17337297056_3d38dc2180_b.jpg" alt=""></p><h3 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to “故障排除”">​</a></h3><ol><li><p>我在运行iked时碰到了如下错误。</p><p>iked: error while loading shared libraries: libss_ike.so.2.2.1: cannot open shared object file: No such file or directory</p></li></ol><p>要解决该问题，你需要更新动态链接器来容纳libss_ike库。对于此，请添加库文件的位置路径到/etc/ld.so.conf文件中，然后运行ldconfig命令。</p><pre><code>$ sudo ldconfig
</code></pre><p>验证libss_ike是否添加到了库路径：</p><pre><code>$ ldconfig -p | grep ike 
</code></pre><hr><pre><code>libss_ike.so.2.2.1 (libc6,x86-64) =&gt; /lib/libss_ike.so.2.2.1
libss_ike.so (libc6,x86-64) =&gt; /lib/libss_ike.so
</code></pre><hr>`,29)),n("p",null,[e[4]||(e[4]=t("via: ",-1)),s(i,{href:"http://ask.xmodulo.com/install-shrew-soft-ipsec-vpn-client-linux.html"},{default:o(()=>[...e[3]||(e[3]=[t("http://ask.xmodulo.com/install-shrew-soft-ipsec-vpn-client-linux.html",-1)])]),_:1})]),n("p",null,[e[8]||(e[8]=t("作者：",-1)),s(i,{href:"http://ask.xmodulo.com/author/nanni"},{default:o(()=>[...e[5]||(e[5]=[t("Dan Nanni",-1)])]),_:1}),e[9]||(e[9]=t(" 译者：",-1)),s(i,{href:"https://github.com/GOLinux"},{default:o(()=>[...e[6]||(e[6]=[t("GOLinux",-1)])]),_:1}),e[10]||(e[10]=t(" 校对：",-1)),s(i,{href:"https://github.com/wxy"},{default:o(()=>[...e[7]||(e[7]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[13]||(e[13]=t("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[11]||(e[11]=[t("LCTT",-1)])]),_:1}),e[14]||(e[14]=t(" 原创翻译，",-1)),s(i,{href:"https://linux.cn/"},{default:o(()=>[...e[12]||(e[12]=[t("Linux中国",-1)])]),_:1}),e[15]||(e[15]=t(" 荣誉推出",-1))])])}const k=l(u,[["render",f]]);export{S as __pageData,k as default};
